insert into port.company_berth_editions(id,ticker,observed_on,entries,review_note) values ('78c1f54b-a0a1-4aa0-b541-8a5f398ab001','GMD','2026-10-24','[{"asset_code": "nam_dinh_vu", "name": "Nam Đình Vũ", "alias": "NAM DINH VU", "operator": "Công ty Cổ phần Cảng Nam Đình Vũ", "relationship": "via_member_company", "source_url": "https://www.gemadept.com.vn/wp-content/uploads/2026/04/20260418_GMD-AR_VN_SmartPDF01.pdf", "source_sha256": "19f18cccab1d93cd8b2db5713d2c82440fce3b5719fceaa0d152a05ec8f25f6a", "source_note": "Phạm vi theo dõi Hải Phòng: Nam Đình Vũ, quan hệ qua pháp nhân theo báo cáo 2025. Không phải toàn bộ tài sản GMD; không chia theo giai đoạn hoặc tỷ lệ vốn.", "effective_from": null, "effective_to": null}]'::jsonb,'Owner requested Hai Phong dashboards; official issuer sources checked, observed physical schedule scope only; no inferred ownership percentages, legal effective dates or nationwide GMD totals.') on conflict(id) do nothing;
