insert into port.company_berth_editions(id,ticker,observed_on,entries,review_note) values ('78c1f54b-a0a1-4aa0-b541-8a5f398ab003','DXP','2026-10-24','[{"asset_code": "doan_xa", "name": "Đoạn Xá", "alias": "DOAN XA", "operator": "Công ty Cổ phần Cảng Đoạn Xá", "relationship": "operator", "source_url": "https://doanxaport.com.vn/gioi-thieu", "source_sha256": "ed34f18ecd1f7c652a2fba592867e1c4b0ac5b860b69db19b47a84ad6fd2f6c3", "source_note": "Trang giới thiệu chính thức xác nhận mã DXP và hoạt động khai thác Cảng Đoạn Xá. Không coi các kho nhựa đường là cảng mới; giữ ngày hiệu lực quan hệ chưa xác định.", "effective_from": null, "effective_to": null}]'::jsonb,'Owner requested Hai Phong dashboards; official issuer sources checked, observed physical schedule scope only; no inferred ownership percentages, legal effective dates or nationwide GMD totals.') on conflict(id) do nothing;
